export const OPERATIONS=["add","subtract","multiply","divide"];export const DEFAULT_OPERATIONS=["add","subtract","multiply"];export const OPERATION_SIGNS={add:"+",subtract:"−",multiply:"×",divide:"÷"};export const MAX_OPERAND=9999;export const MAX_COUNT=100;export const MAX_TIME_LIMIT=3600;const t=4294967296;export function cryptoUint32(){const t=new Uint32Array(1);return globalThis.crypto.getRandomValues(t),t[0]}export function randomInt(n,r,e){const o="function"==typeof e?e:cryptoUint32,a=r-n+1;if(!(a>1))return n;const i=t-t%a;let s=o();for(let t=0;s>=i&&t<32;t++)s=o();return n+s%a}function wholeNumber(t,n){const r=Math.floor(Number(t));return Number.isFinite(r)?r:n}export function parseOperations(t){const n=Array.isArray(t)?t.map(t=>String(t).trim().toLowerCase()):String(t??"").toLowerCase().split(/[\s,]+/),r=OPERATIONS.filter(t=>n.includes(t));return r.length?r:DEFAULT_OPERATIONS.slice()}export function normalizeSettings(t){const n=t||{};let r=Math.min(9999,Math.max(0,wholeNumber(n.min,2))),e=Math.min(9999,Math.max(0,wholeNumber(n.max,12)));if(e<r){const t=r;r=e,e=t}return{operations:parseOperations(n.operations),min:r,max:e,count:Math.min(100,Math.max(1,wholeNumber(n.count,10))),timeLimit:Math.min(3600,Math.max(0,wholeNumber(n.timeLimit,0)))}}export function makeProblem(t,n,r,e){const o=randomInt(n,r,e),a=randomInt(n,r,e);if("subtract"===t){const n=Math.max(o,a),r=Math.min(o,a);return{operation:t,a:n,b:r,answer:n-r}}if("multiply"===t)return{operation:t,a:o,b:a,answer:o*a};if("divide"===t){const a=Math.max(1,n),i=randomInt(a,Math.max(a,r),e);return{operation:t,a:i*o,b:i,answer:o}}return{operation:"add",a:o,b:a,answer:o+a}}export function makeProblems(t,n){const r=normalizeSettings(t),e=[];for(let t=0;t<r.count;t++){let t=null;for(let o=0;o<4;o++){t=makeProblem(r.operations[randomInt(0,r.operations.length-1,n)],r.min,r.max,n);const o=e[e.length-1];if(!o||o.operation!==t.operation||o.a!==t.a||o.b!==t.b)break}e.push(t)}return e}export function parseAnswer(t){const n=String(t??"").trim();if(""===n||n.length>12)return null;for(let t=0;t<n.length;t++){const r=n.charCodeAt(t);if(r<48||r>57)return null}return Number(n)}